import React, { useRef, useEffect } from 'react';
import { Drawer } from 'antd';

const SwipeableDrawer = ({ open, onClose, children, ...props }) => {
  const drawerRef = useRef(null);
  const touchStartX = useRef(0);
  const touchEndX = useRef(0);

  const handleTouchStart = (e) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchMove = (e) => {
    touchEndX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = () => {
    const distance = touchStartX.current - touchEndX.current;
    if (distance > 80) {
      onClose(); // swipe left to close
    }
  };

  useEffect(() => {
    const drawerEl = drawerRef.current?.parentNode; // AntD renders Drawer portal outside of this component
    if (drawerEl) {
      drawerEl.addEventListener('touchstart', handleTouchStart);
      drawerEl.addEventListener('touchmove', handleTouchMove);
      drawerEl.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      if (drawerEl) {
        drawerEl.removeEventListener('touchstart', handleTouchStart);
        drawerEl.removeEventListener('touchmove', handleTouchMove);
        drawerEl.removeEventListener('touchend', handleTouchEnd);
      }
    };
  }, [open]);

  return (
    <Drawer ref={drawerRef} open={open} onClose={onClose} placement="right" {...props}>
      {children}
    </Drawer>
  );
};

export default SwipeableDrawer;
